insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_19_v1'
from (values
('127.110.d.1.A',3,'Which habit shows safe work on a commercial construction site?','["Inspecting tools and the work area before starting", "Removing guards to work faster", "Working alone with no communication", "Skipping inspections to save time"]'::jsonb,0,'Safe procedures begin with inspecting tools and the area.','original'),
('127.110.d.1.A',4,'A crew lead sees a frayed cord on a power tool. What is the correct action?','["Let the next shift handle it", "Tag it out of service and replace it", "Wrap it with tape and keep using it", "Use it only for short jobs"]'::jsonb,1,'Damaged tools are removed from service.','original'),
('127.110.d.1.B',3,'OSHA is a federal agency whose main job is to:','["Set prices for electrical materials", "Collect income taxes from workers", "Set and enforce workplace safety rules", "License all new buildings"]'::jsonb,2,'OSHA protects workers.','original'),
('127.110.d.1.B',4,'A worker can contact OSHA to report:','["A late paycheck only", "A noisy neighbor", "A broken vending machine", "An unsafe condition at the job site"]'::jsonb,3,'Workers may report hazards.','original'),
('127.110.d.1.C',3,'Which situation is an electrical hazard on a jobsite?','["Exposed energized conductors within reach", "Clean and dry floors", "A tool belt hanging on a hook", "A posted safety sign"]'::jsonb,0,'Exposed live parts can shock.','original'),
('127.110.d.1.C',4,'Working with wet hands near a live panel greatly raises the risk of:','["Faster work", "Severe electric shock", "Lower voltage", "Better conductivity of tools"]'::jsonb,1,'Moisture lowers body resistance.','original'),
('127.110.d.1.D',3,'The purpose of a lockout device on a disconnect is to:','["Keep the panel cool", "Speed up the power restore", "Prevent the equipment from being energized during service", "Identify the cheapest breaker"]'::jsonb,2,'Locks keep power off.','original'),
('127.110.d.1.D',4,'After locking out a circuit, the technician should next:','["Remove the lock", "Ask a coworker to turn it on", "Assume it is dead", "Verify with a meter that the circuit is dead"]'::jsonb,3,'Always test for zero energy.','original'),
('127.110.d.2.A',3,'A branch circuit is the wiring that runs from the:','["Final overcurrent device to the outlets it serves", "Utility pole to the meter", "Panel to the grounding rod", "Meter to the street"]'::jsonb,0,'Branch circuits feed loads.','original'),
('127.110.d.2.A',4,'Ampacity is best defined as the:','["Voltage a battery stores", "Current a conductor can carry without overheating", "Resistance of a motor", "Length of a wire run"]'::jsonb,1,'Ampacity limits heat.','original'),
('127.110.d.2.B',3,'A totally enclosed motor enclosure is used where the motor must be protected from:','["Cool air", "Mounting hardware", "Dust and moisture entering the frame", "Operators seeing it"]'::jsonb,2,'Enclosures protect the motor.','original'),
('127.110.d.2.B',4,'An open drip-proof motor is generally best suited to:','["Explosive atmospheres", "Wet washdown rooms", "Dusty grain mills", "Clean indoor areas"]'::jsonb,3,'Open motors need clean air.','original'),
('127.110.d.2.C',3,'A motor nameplate lists 230 V while the system supplies 240 V. This difference shows that motor rated voltage:','["May differ slightly from system voltage", "Must always be exactly equal", "Is a measure of speed", "Is ignored by the code"]'::jsonb,0,'Ratings differ from nominal system voltage.','original'),
('127.110.d.2.C',4,'Running a motor far below its rated voltage usually causes:','["No change", "Higher current and overheating", "Faster speed", "Lower current and cooling"]'::jsonb,1,'Low voltage raises current.','original'),
('127.110.d.2.D',3,'The moving part of a squirrel-cage induction motor is the:','["Frame", "Stator", "Rotor", "Terminal block"]'::jsonb,2,'The rotor turns.','original'),
('127.110.d.2.D',4,'The stator of a three-phase induction motor contains:','["A fuel tank", "Permanent bars only", "Brushes and a commutator", "Windings that create a rotating magnetic field"]'::jsonb,3,'Stator windings create the field.','original'),
('127.110.d.2.E',3,'When supply frequency rises while the pole count is unchanged, synchronous speed will:','["Go up", "Go down", "Reverse direction", "Stay at zero"]'::jsonb,0,'Speed is proportional to frequency.','original'),
('127.110.d.2.E',4,'A 60 Hz, 4-pole motor has a synchronous speed of:','["3600 rpm", "1800 rpm", "900 rpm", "1200 rpm"]'::jsonb,1,'120 x 60 / 4 = 1800.','original'),
('127.110.d.2.F',3,'Torque in an induction motor is developed by the interaction of the rotor currents and the:','["Nameplate", "Frame paint", "Rotating stator magnetic field", "Cooling fan only"]'::jsonb,2,'Field and current make torque.','original'),
('127.110.d.2.F',4,'An induction motor produces torque only when the rotor turns:','["Faster than synchronous speed", "In a vacuum", "Exactly at synchronous speed", "Slower than synchronous speed"]'::jsonb,3,'Slip is required.','original'),
('127.110.d.2.G',3,'When slip grows in an induction motor, rotor current generally:','["Rises", "Stays the same", "Drops to zero", "Reverses"]'::jsonb,0,'More slip, more induced current.','original'),
('127.110.d.2.G',4,'High rotor reactance at starting tends to make the starting power factor:','["Unity", "Low", "Perfect", "Negative"]'::jsonb,1,'Reactance lowers power factor.','original'),
('127.110.d.2.H',3,'Percent slip is found by dividing the speed difference by the:','["Voltage", "Frame size", "Synchronous speed", "Wire gauge"]'::jsonb,2,'Slip = (Ns - N)/Ns.','original'),
('127.110.d.2.H',4,'A motor with synchronous speed 1800 rpm and full-load speed 1740 rpm has a percent slip of:','["33 percent", "0.33 percent", "6.6 percent", "3.3 percent"]'::jsonb,3,'60/1800 = 0.033.','original'),
('127.110.d.2.I',3,'To reverse a three-phase induction motor, swap any:','["Two of the three line leads", "The nameplate", "All three leads", "One ground wire"]'::jsonb,0,'Swapping two reverses rotation.','original'),
('127.110.d.2.I',4,'Swapping two supply leads reverses the motor because it reverses the:','["Voltage level", "Phase sequence", "Frame size", "Frequency"]'::jsonb,1,'Sequence sets direction.','original'),
('127.110.d.2.J',3,'A synchronous motor runs at a speed that is:','["Dependent on load slip", "Always zero", "Locked to the supply frequency", "Random"]'::jsonb,2,'No slip at steady state.','original'),
('127.110.d.2.J',4,'Compared with induction motors, synchronous motors can be used to:','["Run without any supply", "Reduce frame size to zero", "Avoid all maintenance", "Correct a lagging power factor"]'::jsonb,3,'They can supply leading current.','original'),
('127.110.d.2.K',3,'Armature reaction in a DC motor is the effect of armature current on the:','["Main field flux", "Bearing grease", "Nameplate size", "Wire insulation"]'::jsonb,0,'It distorts the field.','original'),
('127.110.d.2.K',4,'At the instant a DC motor starts, armature current is very high because:','["The voltage is lowest", "There is no counter EMF yet", "The brushes are new", "The load is zero"]'::jsonb,1,'No back EMF at standstill.','original'),
('127.110.d.2.L',3,'The rotation of a DC motor is reversed by changing the polarity of the:','["Fuse", "Nameplate", "Armature or the field, but not both", "Frame"]'::jsonb,2,'Reverse one only.','original'),
('127.110.d.2.L',4,'If both armature and field polarity are reversed at once, the DC motor will:','["Stop forever", "Overspeed immediately", "Reverse direction", "Keep turning in the same direction"]'::jsonb,3,'Two reversals cancel.','original'),
('127.110.d.2.M',3,'A series DC motor is known for very high:','["Starting torque", "Frequency", "Speed regulation", "Power factor"]'::jsonb,0,'Series field carries load current.','original'),
('127.110.d.2.M',4,'A shunt DC motor is well suited to jobs needing:','["No field winding", "Nearly constant speed", "Variable frequency", "Extreme starting torque"]'::jsonb,1,'Shunt speed is stable.','original'),
('127.110.d.2.N',3,'A dual-voltage motor can be connected to:','["Only one voltage ever", "DC and AC at once", "Either of two supply voltages by changing leads", "Any voltage at all"]'::jsonb,2,'Winding groups reconnect.','original'),
('127.110.d.2.N',4,'A motor wired for the higher of its two voltages draws:','["More current", "The same current", "No current", "Less current than at the lower voltage"]'::jsonb,3,'Higher voltage, lower current.','original'),
('127.110.d.2.O',3,'Motor lead markings such as T1 through T9 are used to:','["Identify winding ends for connections", "Show the price", "Rate the paint", "Label bearings"]'::jsonb,0,'Leads are numbered.','original'),
('127.110.d.2.O',4,'An ohmmeter is useful for finding motor connections because it can:','["Set the frequency", "Show which leads belong to the same winding", "Create voltage", "Measure rpm"]'::jsonb,1,'Continuity identifies windings.','original'),
('127.110.d.2.P',3,'The NEC requires motor circuits to have overload protection to guard against:','["Spelling errors", "Loud noise", "Sustained overcurrent that heats the windings", "Dim lights"]'::jsonb,2,'Overloads damage motors.','original'),
('127.110.d.2.P',4,'Motor branch-circuit short-circuit protection is generally allowed to be sized:','["Exactly at running current", "Lower than running current", "At zero amperes", "Higher than the motor running current to permit starting"]'::jsonb,3,'Starting current is higher.','original'),
('127.110.d.3.A',3,'A main purpose of grounding electrical systems is to:','["Limit voltage and provide a path for fault current", "Slow down breakers", "Increase the cost", "Raise the voltage"]'::jsonb,0,'Grounding improves safety.','original'),
('127.110.d.3.A',4,'The NEC rules on grounding are found mainly in Article:','["430", "250", "90", "310"]'::jsonb,1,'Article 250 covers grounding and bonding.','original'),
('127.110.d.3.B',3,'A short circuit is an unintended path between:','["A wire and its insulation", "A switch and a lamp", "Two conductors of different potential", "A box and a cover"]'::jsonb,2,'Conductors touch each other.','original'),
('127.110.d.3.B',4,'A ground fault occurs when a live conductor touches:','["Another live phase", "A plastic cover", "Open air", "Grounded metal or earth"]'::jsonb,3,'Ground fault goes to ground.','original'),
('127.110.d.3.C',3,'In NEC terms, a grounded conductor is one that is:','["Intentionally connected to earth", "Always bare", "Colored red", "Never carrying current"]'::jsonb,0,'Usually the neutral.','original'),
('127.110.d.3.C',4,'Bonding in NEC terms means:','["Gluing insulation", "Joining metal parts to form a conductive path", "Cooling wire", "Painting metal"]'::jsonb,1,'Bonding keeps parts at equal potential.','original'),
('127.110.d.3.D',3,'System grounding connects the:','["Meters to poles", "Lamps to switches", "Electrical system''s current-carrying conductor to earth", "Metal enclosures to each other only"]'::jsonb,2,'It stabilizes system voltage.','original'),
('127.110.d.3.D',4,'Equipment grounding is intended mainly to:','["Raise system voltage", "Reduce wire size", "Light the room", "Keep metal parts safe and carry fault current"]'::jsonb,3,'It helps breakers trip.','original'),
('127.110.d.3.E',3,'The grounding electrode conductor size is chosen from the NEC based on the size of the:','["Largest service-entrance conductor", "Building height", "Fixture", "Panel color"]'::jsonb,0,'Table 250.66 uses service size.','original'),
('127.110.d.3.E',4,'A larger service-entrance conductor will generally require a grounding electrode conductor that is:','["Removed", "Larger, up to the maximum allowed", "Unrelated", "Smaller always"]'::jsonb,1,'Tables step up with size.','original'),
('127.110.d.3.F',3,'An NEC requirement for a grounding electrode conductor is that it be:','["Hidden under paint", "Made of string", "Properly protected and continuous or spliced only as allowed", "Left loose"]'::jsonb,2,'Installation must be secure.','original'),
('127.110.d.3.F',4,'A grounding electrode conductor is typically attached to the electrode with:','["Staples", "Electrical tape", "Plain knots", "An approved clamp or exothermic weld"]'::jsonb,3,'Connections must be approved.','original'),
('127.110.d.3.G',3,'A grounding electrode system can include a metal underground water pipe and:','["Concrete-encased electrodes", "A mailbox", "A TV antenna", "Roof shingles"]'::jsonb,0,'Several electrodes are bonded together.','original'),
('127.110.d.3.G',4,'When several electrodes are present at a building, the NEC generally requires them to be:','["Kept isolated", "Bonded together into one system", "Removed", "Painted differently"]'::jsonb,1,'They form a grounding electrode system.','original'),
('127.110.d.3.H',3,'A made electrode such as a ground rod must meet a limit on its:','["Brand", "Paint color", "Resistance to earth", "Weight in tons"]'::jsonb,2,'Resistance is limited, or a second electrode is added.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_19_v1'
from (values
('127.110.d.3.H',4,'If a single rod''s resistance to earth exceeds 25 ohms, the NEC calls for:','["No action", "A thicker rod only", "Removing the rod", "An additional electrode"]'::jsonb,3,'Add a second electrode.','original'),
('127.110.d.3.I',3,'The size of an equipment grounding conductor depends on the rating of the:','["Overcurrent device protecting the circuit", "Floor type", "Light bulb", "Wall color"]'::jsonb,0,'Table 250.122 is used.','original'),
('127.110.d.3.I',4,'For a circuit protected by a 20-ampere breaker, the minimum copper equipment grounding conductor is generally:','["2 AWG", "12 AWG", "18 AWG", "8 AWG"]'::jsonb,1,'NEC Table 250.122 lists 12 AWG for 20 A.','original'),
('127.110.d.3.J',3,'The main bonding jumper connects the grounded service conductor to the:','["Light switch", "Roof", "Service equipment enclosure", "Water heater only"]'::jsonb,2,'It bonds neutral to enclosure at service.','original'),
('127.110.d.3.J',4,'The system bonding jumper is used in a:','["Doorbell", "Battery flashlight", "Garage door", "Separately derived system"]'::jsonb,3,'It bonds the derived neutral to ground.','original'),
('127.110.d.3.K',3,'When a service has multiple disconnects in separate enclosures, the main bonding jumper is sized by the:','["Largest service-entrance conductor per NEC table", "Building age", "Number of windows", "Panel''s paint"]'::jsonb,0,'Size follows the service conductors.','original'),
('127.110.d.3.K',4,'For parallel service conductors, the bonding jumper size is based on the:','["Cable color", "Total area of the parallel conductors in each set combined", "Smallest wire only", "Meter brand"]'::jsonb,1,'Combined area is used.','original'),
('127.110.d.3.L',3,'Metal raceways and enclosures are bonded to ensure:','["Lower safety", "Higher resistance", "Fault current has a low-impedance path back to the source", "Less noise only"]'::jsonb,2,'A solid path lets breakers trip.','original'),
('127.110.d.3.L',4,'Locknuts and bonding bushings on service raceways help:','["Cool the wire", "Hold labels", "Seal paint", "Maintain bonding continuity"]'::jsonb,3,'Service raceways need reliable bonding.','original'),
('127.110.d.3.M',3,'Effective grounding means the path from circuit conductors to ground has low enough impedance to:','["Let the overcurrent device clear the fault quickly", "Raise voltage", "Avoid inspection", "Weaken breakers"]'::jsonb,0,'Fault current must be large enough.','original'),
('127.110.d.3.M',4,'A high-impedance ground path during a fault can leave exposed metal:','["Grounded perfectly", "Energized at a dangerous voltage", "Painted", "Cold"]'::jsonb,1,'Poor path leaves hazard.','original'),
('127.110.d.3.N',3,'The neutral conductor in a grounded system serves to carry:','["All line current", "Only ground faults", "Unbalanced current back to the source", "No current"]'::jsonb,2,'It carries the imbalance.','original'),
('127.110.d.3.N',4,'In a balanced three-phase wye system with equal loads, neutral current is approximately:','["Triple", "Double", "Infinite", "Zero"]'::jsonb,3,'Balanced loads cancel.','original'),
('127.110.d.3.O',3,'A separately derived system, such as a transformer secondary, is grounded at:','["Its source or first disconnect", "Every outlet", "The driveway", "The roof"]'::jsonb,0,'One point of grounding is made.','original'),
('127.110.d.3.O',4,'Grounding a separately derived system at more than one point can cause:','["Lower cost", "Objectionable current on the grounding paths", "Cooler transformers", "Brighter lamps"]'::jsonb,1,'Parallel neutral paths are a problem.','original'),
('127.110.d.3.P',3,'Grounding at more than one building supplied by a feeder is done by installing at each building a:','["Carpet", "Neon sign", "Grounding electrode system", "Paint stripe"]'::jsonb,2,'Each building needs electrodes.','original'),
('127.110.d.3.P',4,'A building fed by a feeder with a separate equipment grounding conductor generally has the neutral and ground:','["Joined at the second building", "Bonded to plumbing only", "Eliminated", "Kept separate at the second building"]'::jsonb,3,'Avoid parallel neutral paths.','original'),
('127.110.d.3.Q',3,'For a high-impedance grounded system, the grounding impedance limits ground-fault:','["Current", "Panel color", "Wall thickness", "Voltage drop of lamps"]'::jsonb,0,'It limits fault current.','original'),
('127.110.d.3.Q',4,'An ungrounded system is often used where a first ground fault should:','["Remove all power instantly", "Not shut down the process", "Add cost", "Cause an explosion"]'::jsonb,1,'Continuity of operation.','original'),
('127.110.d.4.A',3,'Power benders for conduit are used mainly for:','["Painting", "Cutting tape", "Larger conduit sizes", "Wire stripping"]'::jsonb,2,'They bend large sizes.','original'),
('127.110.d.4.A',4,'Using a hydraulic bender helps the user:','["Skip measuring", "Avoid safety rules", "Bend glass", "Make bends with less manual effort"]'::jsonb,3,'Hydraulics supply force.','original'),
('127.110.d.4.B',3,'The part of a bender that forms the curve in the conduit is the:','["Shoe", "Handle grip", "Foot pedal cord", "Frame leg only"]'::jsonb,0,'Shoe defines radius.','original'),
('127.110.d.4.B',4,'On a hydraulic bender, the ram pushes the conduit against the:','["Tape measure", "Bending shoe", "Floor plate", "Wire reel"]'::jsonb,1,'The ram drives the bend.','original'),
('127.110.d.4.C',3,'To avoid wasting conduit, an electrician should:','["Bend at random", "Use extra on every run", "Measure carefully and plan bends before cutting", "Cut first and guess"]'::jsonb,2,'Planning reduces scrap.','original'),
('127.110.d.4.C',4,'Marking a conduit with the take-up and bend locations helps:','["Create more scrap", "Hide the bends", "Delay the job", "Prevent mistakes that waste material"]'::jsonb,3,'Careful marks save conduit.','original'),
('127.110.d.4.D',3,'A saddle bend is used when conduit must:','["Cross over an obstruction", "Be buried", "End in a box", "Run straight"]'::jsonb,0,'Saddles clear obstacles.','original'),
('127.110.d.4.D',4,'Parallel bends in side-by-side conduits keep the runs:','["Crossed", "Evenly spaced and neat", "Touching", "Random"]'::jsonb,1,'Parallel bends match.','original'),
('127.110.d.4.E',3,'The NEC limits the number of bends in one run between pull points to:','["90 degrees total", "900 degrees total", "360 degrees total", "No limit"]'::jsonb,2,'Four quarter bends maximum.','original'),
('127.110.d.4.E',4,'The NEC sets minimum bending radius so that conduit:','["Looks tall", "Costs more", "Is lighter", "Is not damaged and conductors can be pulled"]'::jsonb,3,'Radius tables protect wires.','original'),
('127.110.d.4.F',3,'The developed length of a bend is the length of:','["Conduit used along the curve", "The whole building", "The pulling rope", "The bender handle"]'::jsonb,0,'It is the arc length.','original'),
('127.110.d.4.F',4,'Gain in a 90-degree bend is the amount by which the bend:','["Adds extra length", "Shortens the overall run compared with square corners", "Changes voltage", "Equals zero always"]'::jsonb,1,'Gain saves conduit.','original'),
('127.110.d.4.G',3,'Conduit that has a kink should be:','["Painted", "Taped", "Replaced because the kink damages the pull path", "Pulled anyway"]'::jsonb,2,'Kinks harm wires.','original'),
('127.110.d.4.G',4,'To modify an existing bend, the electrician may:','["Hammer it flat", "Heat it with a lighter", "Cut it with a torch", "Reshape it carefully with the proper bender without kinking"]'::jsonb,3,'Use correct tools.','original'),
('127.110.d.5.A',3,'A common nonmetallic box material is:','["PVC or other plastic", "Cast iron only", "Wood", "Glass"]'::jsonb,0,'Nonmetallic boxes are plastic.','original'),
('127.110.d.5.A',4,'A metal box must be grounded, while a nonmetallic box generally does not need:','["Any cover", "To be bonded itself", "Any support", "Any conductors"]'::jsonb,1,'Plastic is nonconductive.','original'),
('127.110.d.5.B',3,'Box fill depends on the number and size of the conductors, devices, and:','["Ceiling height", "Floor type", "Clamps and fittings inside the box", "Paint"]'::jsonb,2,'Fill counts volume allowances.','original'),
('127.110.d.5.B',4,'A box holding more conductors than the NEC allows can cause:','["Faster pulling", "Better cooling", "Lower voltage", "Overheating from crowding"]'::jsonb,3,'Overfill is unsafe.','original'),
('127.110.d.5.C',3,'NEC box volume allowances are given in:','["Cubic inches per conductor size", "Pounds", "Square feet", "Miles"]'::jsonb,0,'Table 314.16(B).','original'),
('127.110.d.5.C',4,'A 14 AWG conductor requires how much volume allowance in a box?','["0.25 cubic inches", "2.00 cubic inches", "5.00 cubic inches", "8.00 cubic inches"]'::jsonb,1,'Table lists 2.00 for 14 AWG.','original'),
('127.110.d.5.D',3,'Boxes must be installed so they are:','["Hidden behind paneling", "Loose in the wall", "Securely supported and accessible", "Buried in concrete without access"]'::jsonb,2,'Boxes must be reachable.','original'),
('127.110.d.5.D',4,'A box installed in a masonry wall is typically supported by:','["Spray foam", "Hot glue", "Drywall tape", "Anchors suited to masonry"]'::jsonb,3,'Anchors give strength.','original'),
('127.110.d.5.E',3,'The NEC sets minimum pull-box size for large conductors so wires can be:','["Pulled and bent without damage", "Colored", "Hidden", "Cut shorter"]'::jsonb,0,'Sizing reduces stress.','original'),
('127.110.d.5.E',4,'For a straight pull of conductors 4 AWG or larger, the box length must be at least how many times the largest raceway trade diameter?','["Twenty", "Eight", "Two", "Four"]'::jsonb,1,'Straight pull is 8 times.','original'),
('127.110.d.5.F',3,'The radius rule in a pull box prevents conductors from being:','["Painted", "Labeled", "Bent too sharply", "Cooled"]'::jsonb,2,'Minimum bending radius protects insulation.','original'),
('127.110.d.5.F',4,'Under the radius rule, large cable should not be forced into a corner that is:','["Labeled in black", "Wider than the cable", "Painted white", "Tighter than the permitted bend radius"]'::jsonb,3,'Bend radius is limited.','original'),
('127.110.d.5.G',3,'Heavy luminaires must be supported by a box that is:','["Listed for the weight", "Painted", "Any size", "Open"]'::jsonb,0,'Boxes carry loads.','original'),
('127.110.d.5.G',4,'A ceiling fan box is different from a basic light box because it is:','["Open on one side", "Rated to carry the fan weight and motion", "Smaller", "Made of paper"]'::jsonb,1,'Fan boxes are listed for fans.','original'),
('127.110.d.5.H',3,'A conduit body, like an LB, is used to:','["Measure voltage", "Cut wire", "Provide a pulling access point at a bend", "Replace the panel"]'::jsonb,2,'Conduit bodies give access.','original'),
('127.110.d.5.H',4,'A Type FS box is commonly used with:','["Plumbing pipe", "Underground cable", "Flat cable only", "Surface-mounted rigid or EMT conduit"]'::jsonb,3,'FS boxes are for conduit.','original'),
('127.110.d.5.I',3,'Fittings used with boxes should be:','["Listed for the conduit and box type", "Any scrap", "Painted", "Homemade"]'::jsonb,0,'Match the fitting.','original'),
('127.110.d.5.I',4,'Connectors that enter a box through a knockout must be secured with a:','["String", "Locknut or equivalent", "Tape", "Rubber band"]'::jsonb,1,'Locknuts hold fittings.','original'),
('127.110.d.5.J',3,'Boxes and fittings in hazardous areas must be:','["Plastic only", "Open", "Listed for the classified location", "Unmarked"]'::jsonb,2,'Hazardous locations need listed gear.','original'),
('127.110.d.5.J',4,'Explosionproof fittings are required to:','["Look decorative", "Be lightweight", "Vent sparks outward", "Contain an internal explosion and cool escaping gases"]'::jsonb,3,'They stop flame propagation.','original'),
('127.110.d.5.K',3,'Selecting a box includes checking the number of conductors, device type, and the:','["Location conditions", "Brand of coffee", "Date", "Owner''s age"]'::jsonb,0,'Environment matters.','original'),
('127.110.d.5.K',4,'A box in a damp location should be:','["Cardboard", "Listed for damp or wet use", "Unlisted", "Open"]'::jsonb,1,'Moisture needs ratings.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
